{
  "гриб": "Amanita rubescens (мухомор серо-розовый, мухомор пестрый)",
  "состав": [
    {
      "вещество": "Рубесцеол (C36H60O8)",
      "содержание": "неизвестно (часть общего пула сапонинов, совокупно ~5–8 % от сухого веса)",
      "влияние": "Стероидный сапонин, придающий мякоти выраженный горький вкус; при умеренном количестве нетоксичен, но делает гриб непригодным к еде без длительной варки и сливания."
    },
    {
      "вещество": "Рубросцин (C22H38O6)",
      "содержание": "неизвестно (входит в общий пул сапонинов)",
      "влияние": "Тритерпеноидный сапонин, усиливает горечь и горьковатый привкус, характерный для сухих и сушёных плодовых тел."
    },
    {
      "вещество": "Руберин (C38H64O8)",
      "содержание": "неизвестно (входит в общий пул сапонинов)",
      "влияние": "Тритерпеноидный сапонин, вносит вклад в стойкую горькость; не является истинным токсином, но вызывает лёгкое раздражение слизистой при поедании сырого гриба."
    },
    {
      "вещество": "Эргостерол (C28H44O)",
      "содержание": "~1–3 % от сухого веса (типичный уровень для грибов Basidiomycota)",
      "влияние": "Основной грибо-стерол, провитамин D2; при окислении или УФ-облучении переходит в эргостерол-пероксид и эргокальциферол."
    },
    {
      "вещество": "Эргостерол-пероксид (C28H44O2)",
      "содержание": "неизвестно (вторичный окислительный продукт, обычно < 0,5 % от сухого веса)",
      "влияние": "Обладает умеренной антиоксидантной и антибактериальной активностью; сам по себе нетоксичен в пищевых дозах."
    },
    {
      "вещество": "β-Глюканы / гетеро-β-глюканы (полисахариды)",
      "содержание": "~10–30 % от сухого веса (оценка для Amanita spp.)",
      "влияние": "Высокомолекулярные полисахариды; при пероральном приёме могут стимулировать активность NK-клеток и макрофагов, однако у человека значимый эффект проявляется преимущественно в экстрактах, а не в варёном грибе."
    },
    {
      "вещество": "Маннит (C6H14O6)",
      "содержание": "неизвестно (обычно 0,5–2 % от сухого веса у базидиомицетов)",
      "влияние": "Осмотически активный сахарный спирт; в пищевых количествах нейтрален, в больших дозах может вызывать лёгкое осмотическое слажение."
    }
  ]
}

{
