    },
    {
      "вещество": "Агаринин",
      "содержание": "≈0,01–0,05 % от сухого веса",
      "влияние": "Алкалоид, придающий слабый горьковатый привкус; в количествых, свойственных A. caesarea, не вызывает выраженной токсичности."
    },
    {
      "вещество": "Аманин",
      "содержание": "следовые количества (не более 0,01 % от сухого веса)",
      "влияние": "Слабый горький алкалоид; при таких дозах практически не влияет на метаболизм человека."
    },
    {
      "вещество": "Аманитол",
      "содержание": "не обнаружен (ниже 0,01 % от сухого веса)",
      "влияние": "Циклический сахарный спирт, ингибирующий синтез белка и вызывающий гепато- и нефротоксичность; в A. caesarea его концентрация пренебрежимо мала."
    },
    {
      "вещество": "α-Аманитин",
      "содержание": "не обнаружен",
      "влияние": "Циклический пептид-ингибитор РНК-полимеразы II; при отсутствии в грибе не блокирует транскрипцию и не вызывает некроза гепатоцитов."
    },
    {
      "вещество": "β-Аманитин",
      "содержание": "не обнаружен",
      "влияние": "Гемоциклический пептид, менее токсичный, чем α-аманитин; в A. caesarea в значимых дозах отсутствует."
    },
    {
      "вещество": "Гипсозин",
      "содержание": "неизвестно (отмечен в следовых количествах)",
      "влияние": "Стереоидный сaponиноподобный компонент, придающий лёгкий горьковатый оттенок вкусу, без выраженного фармакологического действия."
    }
  ]
}
